from pathlib import Path
import re

path = Path('/home/ubuntu/crest-automotive-astro/src/layouts/SiteLayout.astro')
text = path.read_text()

text = text.replace("const { title, description = 'Premium, waterless automotive care for DLF Gurugram.', currentPath = '/', pageNumber = '', pageLabel = '' } = Astro.props;", "const { title, description = 'Premium, waterless automotive care for DLF Gurugram.', currentPath = '/', pageNumber = '', pageLabel = '' } = Astro.props;\nconst siteUrl = (import.meta.env.PUBLIC_SITE_URL || '').replace(/\\/$/, '');\nconst canonicalUrl = siteUrl ? `${siteUrl}${Astro.url.pathname}` : undefined;\nconst socialImage = siteUrl ? `${siteUrl}/images/generated/crest-hero-studio.jpg` : '/images/generated/crest-hero-studio.jpg';\nconst localBusinessJsonLd = {\n  '@context': 'https://schema.org',\n  '@type': 'Auto detailing',\n  name: 'Crest Automotive',\n  description,\n  url: canonicalUrl || Astro.url.href,\n  telephone: '+91 98716 10952',\n  areaServed: ['The Camellias, DLF Gurugram', 'The Crest, DLF Gurugram', 'The Magnolias, DLF Gurugram'],\n  serviceType: ['Car detailing', 'Ceramic coating', 'Paint protection film', 'Waterless car wash'],\n  priceRange: '₹₹'\n};\nconst webSiteJsonLd = { '@context': 'https://schema.org', '@type': 'WebSite', name: 'Crest Automotive', url: canonicalUrl || Astro.url.href, description };" )

text = text.replace("<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin=\"anonymous\" />\n    <link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\" />", "<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin=\"anonymous\" />\n    <link href=\"https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\" />")

text = text.replace("<meta name=\"description\" content={description} />\n    <title>{title} | Crest Automotive</title>", "<meta name=\"description\" content={description} />\n    {canonicalUrl && <link rel=\"canonical\" href={canonicalUrl} />}\n    <meta name=\"robots\" content=\"index,follow,max-image-preview:large\" />\n    <meta property=\"og:type\" content=\"website\" />\n    <meta property=\"og:site_name\" content=\"Crest Automotive\" />\n    <meta property=\"og:title\" content={`${title} | Crest Automotive`} />\n    <meta property=\"og:description\" content={description} />\n    <meta property=\"og:image\" content={socialImage} />\n    {canonicalUrl && <meta property=\"og:url\" content={canonicalUrl} />}\n    <meta name=\"twitter:card\" content=\"summary_large_image\" />\n    <meta name=\"twitter:title\" content={`${title} | Crest Automotive`} />\n    <meta name=\"twitter:description\" content={description} />\n    <meta name=\"twitter:image\" content={socialImage} />\n    <title>{title} | Crest Automotive</title>")

text = text.replace("    <ClientRouter />\n  </head>", "    <script type=\"application/ld+json\" set:html={JSON.stringify(localBusinessJsonLd)}></script>\n    <script type=\"application/ld+json\" set:html={JSON.stringify(webSiteJsonLd)}></script>\n    <ClientRouter />\n  </head>")

new_global = '''<style is:global>\n  :root { --ink:#071528; --ink-2:#0b2038; --panel:#102743; --gold:#e2b968; --gold-soft:#f2d18a; --white:#fffdf7; --muted:#fffdf7; --line:rgba(222,181,92,.22); --max:1240px; --ease:cubic-bezier(.23,1,.32,1); }\n  a { color:inherit; text-decoration:none; }\n  button,input,select,textarea { box-sizing:border-box; font:inherit; }\n  select option { color:var(--ink); background:var(--white); }\n  select option:checked { color:var(--white); background:var(--ink-2); }\n  .button { display:inline-flex; box-sizing:border-box; align-items:center; justify-content:center; gap:18px; min-height:54px; padding:0 24px; border:1px solid transparent; border-radius:999px; font-size:10px; font-weight:700; letter-spacing:.08em; text-transform:uppercase; transition:transform .18s var(--ease),background .25s ease,border-color .25s ease,color .25s ease,box-shadow .25s ease; }\n  .button:hover { transform:translateY(-3px); }\n  .button:active { transform:scale(.97); }\n  .button-gold { color:var(--ink); background:linear-gradient(135deg,#e2b968,#f2d18a); box-shadow:inset 0 1px rgba(255,255,255,.45); }\n  .button-gold:hover { color:var(--ink); background:var(--gold-soft); box-shadow:0 14px 32px rgba(226,185,104,.18); }\n  .button-ghost { border-color:#718198; color:var(--white); background:linear-gradient(135deg,rgba(226,185,104,.06),rgba(11,32,56,.72)); }\n  .button-ghost:hover { color:var(--white); border-color:var(--gold); background:rgba(226,185,104,.10); }\n  .button-small { min-height:42px; padding:0 15px; font-size:9px; }\n  main p,main li { color:var(--white) !important; font-size:clamp(14px,1vw,16px); }\n  main small,main label,main .matrix-note,main .matrix-heading>span,main .form-note,main .form-required-note,main .calc-source-note,main .map-label small,main .faq-visual small,main .not-found-mark span,main .not-found-mark small { color:var(--white) !important; }\n  main .eyebrow { color:var(--gold) !important; }\n  main .calculator-controls>label,main .calc-dependent-fields>label,main .calc-check span small,main .calc-summary-lines span,main .calc-total span,main .calc-breakdown,main .calc-source-note,main .estimate-note small,main .matrix-note,main .matrix-heading>span,main th,main td,main .service-price small,main .from-price small,main .coating-card em,main .addon-card>strong small,main .addon-card>div span,main .contact-details small,main .chat-footnote { color:var(--white) !important; }\n  .chatbot .chat-message,.chatbot .chat-footnote,.chatbot-launcher-copy small { color:var(--white) !important; }\n  main h1 { font-size:clamp(44px,5.5vw,72px) !important; }\n  main h2 { font-size:clamp(34px,4vw,52px) !important; }\n  main h3 { font-size:clamp(18px,1.6vw,24px) !important; }\n  main a:not(.button) { color:var(--gold-soft); text-decoration:none; }\n  main a:not(.button):hover { color:var(--white); }\n  .site-footer,.site-footer p,.site-footer a,.site-footer span,.site-footer small { color:var(--white); }\n  .site-footer a:hover { color:var(--gold-soft); }\n  a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible { outline:2px solid var(--gold-soft); outline-offset:4px; }\n  @media (max-width:620px) { .cursor-glow { display:none; } }\n</style>'''
text = re.sub(r'<style is:global>.*?</style>', new_global, text, count=1, flags=re.S)

# Keep the root token definition in one place and make the typography slightly more editorial.
text = text.replace("body { margin: 0; color: var(--white); background: var(--ink); font-family: 'Poppins', sans-serif;", "body { margin: 0; color: var(--white); background: var(--ink); font-family: 'Poppins', sans-serif;")
text = text.replace("h1,h2,h3", "h1,h2,h3")
path.write_text(text)
